#!/bin/sh
# Copies the payloads of the contract into the test bundle.
#
# The contract has one home, ../hermes/docs/fixtures, and is not forked here: what lands in
# Core/Tests/HermesCoreTests/Fixtures is generated by this script and stays out of git. Point
# HERMES_CONTRACT_FIXTURES at the directory when the two repositories are not siblings.
set -eu

cd "$(dirname "$0")/.."

dst="Core/Tests/HermesCoreTests/Fixtures"

# A worktree of this repository sits beside the contract one level deeper than the main checkout.
src=""
for candidate in "${HERMES_CONTRACT_FIXTURES:-}" ../hermes/docs/fixtures ../../hermes/docs/fixtures; do
	if [ -n "$candidate" ] && [ -d "$candidate" ]; then
		src="$candidate"
		break
	fi
done

if [ -z "$src" ]; then
	echo "no ../hermes/docs/fixtures, so the payloads are not copied; the tests that replay them skip themselves"
	exit 0
fi

find "$dst" -mindepth 1 -maxdepth 1 -type d -exec rm -rf {} +
cp -R "$src"/* "$dst"/
echo "copied $(find "$dst" -name '*.json' | wc -l | tr -d ' ') payloads from $src"
